from fractions import Fraction

def find_rho(tol: float = 1e-15, max_iter: int = 200) -> float:
    """Bisection for the unique root of x^3 + x^2 - 1 in (0, 1)."""
    lo, hi = 0.0, 1.0
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        if mid ** 3 + mid ** 2 - 1.0 < 0.0:
            lo = mid
        else:
            hi = mid
        if hi - lo < tol:
            break
    return 0.5 * (lo + hi)

if __name__ == "__main__":
    rho = find_rho()
    mu = 1.0 + rho
    print(f"rho = {rho:.15f}")
    print(f"mu  = 1 + rho = {mu:.15f}")
    print(f"envelope 0.7548 < rho < 0.7549 : {0.7548 < rho < 0.7549}")
    print(f"cubic mu^3-2mu^2+mu-1 = {mu**3 - 2*mu**2 + mu - 1:.2e}")
    print(f"self-similarity rho^2*mu - 1 = {rho**2 * mu - 1:.2e}")

