from typing import Callable

def monotone_root(f: Callable[[float], float], lo: float, hi: float,
                  tol: float = 1e-15, max_iter: int = 300) -> float:
    """Root of a strictly increasing f on [lo, hi] with f(lo) < 0 < f(hi)."""
    assert f(lo) < 0.0 < f(hi)
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        if f(mid) < 0.0:
            lo = mid
        else:
            hi = mid
        if hi - lo < tol:
            break
    return 0.5 * (lo + hi)

def rho_value() -> float:
    return monotone_root(lambda x: x**3 + x**2 - 1.0, 0.0, 1.0)
